#!/usr/bin/env python3
"""Apply or push the Code Graph Dual-View implementation to ExtractExperimenting-web.

Usage Option 1 (Push directly to GitHub via REST API using your token):
    python apply_code_graph_dual_view.py --push --token <YOUR_GITHUB_TOKEN>

Usage Option 2 (Apply directly to a local clone of ExtractExperimenting-web):
    python apply_code_graph_dual_view.py --local /path/to/ExtractExperimenting-web
"""
from __future__ import annotations

import argparse
import base64
import json
import os
from pathlib import Path
import sys
import urllib.error
import urllib.request

REPO_OWNER = "vidhidhaduk05"
REPO_NAME = "ExtractExperimenting-web"
DEFAULT_BRANCH = "main"

EMBEDDED_FILES_B64 = {
    "radextract_platform/backend/routers/graphify.py": "",
    "radextract_platform/backend/tests/test_graphify_router.py": "",
    "radextract_platform/frontend/src/pages/CodeGraphPage.tsx": ""
}


def patch_api_ts_content(original_text: str) -> str:
    """Prevent silent demo fallback for /graphify/code/* in api.ts unless explicitly requested."""
    marker = "// [CODE_GRAPH_DUAL_VIEW_NO_SILENT_FALLBACK]"
    if marker in original_text:
        return original_text
    target = "if (path.startsWith('/graphify/code/graph'))"
    alt_target = 'if (path.startsWith("/graphify/code/graph"))'
    guard = (
        f"{marker}\n"
        "  if (path.startsWith('/graphify/code/') && !path.includes('use_sample=true')) {\n"
        "    throw new Error('Graphify code graph backend unavailable; silent demo fallback is disabled.');\n"
        "  }\n  "
    )
    if target in original_text:
        return original_text.replace(target, guard + target, 1)
    if alt_target in original_text:
        return original_text.replace(alt_target, guard + alt_target, 1)
    return original_text


def apply_local(repo_dir: Path) -> None:
    if not repo_dir.exists():
        raise FileNotFoundError(f"Local repository directory not found: {repo_dir}")
    for rel_path, b64_data in EMBEDDED_FILES_B64.items():
        dest = repo_dir / rel_path
        dest.parent.mkdir(parents=True, exist_ok=True)
        dest.write_bytes(base64.b64decode(b64_data))
        print(f"[UPDATED] {dest}")

    api_ts_path = repo_dir / "radextract_platform/frontend/src/lib/api.ts"
    if api_ts_path.exists():
        orig = api_ts_path.read_text(encoding="utf-8")
        patched = patch_api_ts_content(orig)
        if patched != orig:
            api_ts_path.write_text(patched, encoding="utf-8")
            print(f"[PATCHED] {api_ts_path} (disabled silent demo fallback for /graphify/code/*)")
        else:
            print(f"[INFO] {api_ts_path} already patched or uses custom fallback handler")


def github_api_request(url: str, token: str, method: str = "GET", payload: dict | None = None) -> dict:
    headers = {
        "Accept": "application/vnd.github+json",
        "Authorization": f"Bearer {token}",
        "X-GitHub-Api-Version": "2022-11-28",
        "User-Agent": "RadExtract-CodeGraph-Updater",
    }
    data = None
    if payload is not None:
        data = json.dumps(payload).encode("utf-8")
        headers["Content-Type"] = "application/json"
    req = urllib.request.Request(url, data=data, headers=headers, method=method)
    with urllib.request.urlopen(req, timeout=30) as resp:
        return json.loads(resp.read().decode("utf-8"))


def push_to_github(token: str, branch: str = DEFAULT_BRANCH) -> None:
    base_api = f"https://api.github.com/repos/{REPO_OWNER}/{REPO_NAME}/contents"
    for rel_path, b64_data in EMBEDDED_FILES_B64.items():
        file_url = f"{base_api}/{rel_path}"
        sha = None
        try:
            existing = github_api_request(f"{file_url}?ref={branch}", token=token, method="GET")
            sha = existing.get("sha")
        except urllib.error.HTTPError as e:
            if e.code != 404:
                raise
        payload = {
            "message": f"feat(code-graph): implement Dual-View plan in {Path(rel_path).name}",
            "content": b64_data,
            "branch": branch,
        }
        if sha:
            payload["sha"] = sha
        res = github_api_request(file_url, token=token, method="PUT", payload=payload)
        commit_sha = res.get("commit", {}).get("sha", "")[:7]
        print(f"[PUSHED] {rel_path} -> {branch} (commit {commit_sha})")

    # Also patch radextract_platform/frontend/src/lib/api.ts on GitHub if present
    api_rel = "radextract_platform/frontend/src/lib/api.ts"
    api_url = f"{base_api}/{api_rel}"
    try:
        existing_api = github_api_request(f"{api_url}?ref={branch}", token=token, method="GET")
        raw_api = base64.b64decode(existing_api["content"]).decode("utf-8")
        patched_api = patch_api_ts_content(raw_api)
        if patched_api != raw_api:
            res = github_api_request(
                api_url,
                token=token,
                method="PUT",
                payload={
                    "message": "fix(api): disable silent demo fallback for /graphify/code/* endpoints",
                    "content": base64.b64encode(patched_api.encode("utf-8")).decode("ascii"),
                    "sha": existing_api["sha"],
                    "branch": branch,
                },
            )
            commit_sha = res.get("commit", {}).get("sha", "")[:7]
            print(f"[PUSHED] {api_rel} -> {branch} (commit {commit_sha})")
    except Exception as exc:
        print(f"[NOTE] Skipped remote api.ts patch ({exc}); CodeGraphPage.tsx already enforces direct truthful fetch.")


def main() -> None:
    parser = argparse.ArgumentParser(description="Apply or push Code Graph Dual-View updates.")
    parser.add_argument("--local", type=Path, help="Path to local ExtractExperimenting-web checkout")
    parser.add_argument("--push", action="store_true", help="Push directly to GitHub via REST API")
    parser.add_argument("--token", type=str, default=os.environ.get("GITHUB_TOKEN", ""), help="GitHub PAT")
    parser.add_argument("--branch", type=str, default=DEFAULT_BRANCH, help="Target GitHub branch (default: main)")
    args = parser.parse_args()

    if args.local:
        apply_local(args.local)
    if args.push:
        if not args.token:
            print("ERROR: Provide --token <YOUR_GITHUB_TOKEN> or set GITHUB_TOKEN env var.", file=sys.stderr)
            sys.exit(1)
        push_to_github(args.token.strip(), branch=args.branch)
    if not args.local and not args.push:
        parser.print_help()


if __name__ == "__main__":
    main()